WITH ValidEmployees AS (SELECT * FROM employees WHERE YEAR(hire_date) = 2024), summary AS (SELECT CASE WHEN salary >= 128000 THEN 'high' WHEN salary >= 72000 THEN 'mid' ELSE 'low' END AS salary_bucket, COUNT(*) AS cnt FROM ValidEmployees GROUP BY CASE WHEN salary >= 128000 THEN 'high' WHEN salary >= 72000 THEN 'mid' ELSE 'low' END) SELECT salary_bucket, cnt FROM summary ORDER BY cnt DESC, salary_bucket;
